// =====================================================================
//  JOB HUNT AGENT v2 — CONFIG + PROFILE
// =====================================================================
// Everything downstream reads from this node via $('Config & Profile').
// Only put REAL facts in `profile`.
// Generators are instructed to use nothing outside this profile.
// =====================================================================

const config = {
  model: 'google/gemini-3.1-flash-lite',

  // Cost control: keep runs bounded.
  maxAiJobsPerRun: 10,
  maxPackagesPerRun: 5,
  minMatchScore: 60,
  minSkillsScore: 15,

  // Deterministic filter
  maxYearsExperience: 3,

  // EDIT: where you can work. Matching is a lower-case substring test.
  locationPolicy: {
    acceptRemote: true,

    // Remote jobs are kept when their region text is empty or contains one of these.
    // Add your country / region, e.g. 'europe', 'emea', 'latam', 'usa', 'canada', 'india', 'apac'.
    acceptedRemoteRegions: [
      'worldwide',
      'anywhere',
      'global',
    ],

    // On-site / hybrid jobs are kept only when their location contains one of these.
    // Empty = on-site jobs are all dropped. Add your country and cities, e.g. 'germany', 'berlin'.
    acceptedLocations: [],
  },

  // Direct company job boards via PUBLIC ATS APIs. No login, no scraping.
  // EDIT: add the companies you want to follow. Empty = source reported as NOT CONFIGURED.
  // `board` is the company's slug on that ATS. Check it first in a browser:
  //   Greenhouse: https://boards-api.greenhouse.io/v1/boards/<board>/jobs
  //   Lever:      https://api.lever.co/v0/postings/<board>?mode=json
  // Format: { board: '<slug>', company: '<display name>' }
  atsBoards: {
    greenhouse: [],
    lever: [],
  },

  // Notification (optional).
  // Paste your Discord channel webhook URL here when ready.
  discord: {
  jobsWebhookUrl: '',
  healthWebhookUrl: '',
},

  // Tracker workflow.
  trackerBaseUrl: 'http://localhost:5678/webhook/job-hunt',

  // Questions answered for every shortlisted job.
  applicationQuestions: [
    'Why do you want to work at this company?',
    'Why are you a good fit for this role?',
    'Describe a project you built that is relevant to this role.',
    'What is your availability / start date?',
  ],
};

const profile = {
  // EXAMPLE PROFILE — replace every value with your own REAL facts.
  // The generators may only use what is written here.
  name: 'Alex Example',
  email: 'alex@example.com',
  phone: '+00 00000 00000',

  // Country you live in / can work from. The analysis prompt scores location against it.
  location: 'Example Country',

  links: {
    github: 'https://github.com/your-username',
    linkedin: 'https://www.linkedin.com/in/your-profile/',
    portfolio: 'https://example.com/',
  },

  education: {
    status: 'third-year undergraduate student',
    degree: 'Bachelor of Engineering in Information Technology',
    institution: 'Example Institute of Technology',
    location: 'Example City, Example Country',
    expectedGraduation: '2028',
  },

  availability:
    'Available for a full-time internship during summer break; part-time during the semester.',

  targetRoles: [
    'Software Developer Intern',
    'Backend Engineer Intern',
    'Graduate Software Engineer',
  ],

  interests: [
    'developer tooling',
    'databases',
    'web services',
  ],

  skills: {
    languages: ['TypeScript', 'JavaScript', 'SQL', 'Python'],
    frontend: ['React', 'Tailwind CSS'],
    backend: ['Node.js', 'Express.js', 'REST APIs'],
    ai: [],
    databases: ['PostgreSQL', 'Redis'],
    devops: ['Docker', 'GitHub Actions', 'Linux'],
    other: ['Web services', 'Developer tooling'],
  },

  projects: [
    {
      name: 'Example Notes API',
      summary: 'REST API for personal notes with full-text search.',
      tech: ['Node.js', 'Express.js', 'PostgreSQL', 'Docker'],
      repo: 'https://github.com/your-username/example-notes-api',
      highlights: [
        'Built a REST API for creating, tagging and searching notes.',
        'Implemented PostgreSQL full-text search.',
        'Packaged the service with Docker.',
      ],
    },
    {
      name: 'Example Dashboard',
      summary: 'React dashboard that visualises data from a public API.',
      tech: ['React', 'TypeScript', 'Tailwind CSS'],
      repo: 'https://github.com/your-username/example-dashboard',
      highlights: [
        'Built a responsive dashboard with React and TypeScript.',
        'Added client-side caching of API responses.',
      ],
    },
  ],

  openSource: [
    {
      project: 'Example OSS Library',
      contribution: 'Fixed an off-by-one error in pagination and added a regression test.',
      tech: ['TypeScript'],
      url: 'https://github.com/example-org/example-lib/pull/1',
    },
  ],

  experience: [
    {
      role: 'Software Engineering Intern',
      organization: 'Example Company',
      location: 'Remote',
      start: '2025-06',
      end: '2025-08',
      bullets: [
        'Added input validation to three REST endpoints.',
        'Wrote integration tests for the billing service.',
      ],
    },
  ],
};

// Flat list used for cheap keyword scoring.
const skillList = Object.values(profile.skills).flat();

// Authoritative whitelists derived from the profile (never from model output).
// skillWhitelist: the ONLY skills that may be treated as the candidate's (declared skills + tech of own projects).
// projectTech: the ONLY technologies a generated sentence may attach to each project.
const skillWhitelist = [...new Set([...skillList, ...profile.projects.flatMap((p) => p.tech)])];
const projectTech = Object.fromEntries(profile.projects.map((p) => [p.name, p.tech]));

return [
  {
    json: {
      config,
      profile,
      skillList,
      skillWhitelist,
      projectTech,
      runStartedAt: new Date().toISOString(),
    },
  },
];

const SOURCE = 'arbeitnow';
// Maps the raw API response to the minimal per-source shape. The shared
// "Normalize & Deduplicate" node does the heavy lifting (HTML, salary, keys).
//
// FAULT ISOLATION: this node never throws. Timeout, HTTP 4xx/5xx, 429, bad JSON,
// empty response or a parsing bug all become ONE `sourceError` item, so this
// source contributes zero jobs and every other source keeps going.
const errorItem = (message) => ({ json: { _kind: 'sourceError', source: SOURCE, message: String(message).slice(0, 500) } });
const errMsg = (r) => {
  const e = r && r.error;
  if (!e) return 'Malformed response (expected job list not found)';
  if (typeof e === 'string') return e;
  const code = e.httpCode || e.status || e.statusCode || (e.cause && e.cause.status);
  let msg = String(e.message || e.description || JSON.stringify(e));
  if (/<!doctype|<html/i.test(msg)) msg = msg.replace(/\s*-?\s*"?<!doctype[\s\S]*$|\s*-?\s*"?<html[\s\S]*$/i, '').trim() || 'HTML error page';
  msg = msg.split('\n')[0].replace(/^\d{3}\s*-?\s*/, '').slice(0, 160) || 'error';
  const kind = code ? '' : /timeout|ETIMEDOUT|ECONNABORTED/i.test(msg) ? 'timeout: ' : /ENOTFOUND|ECONNREFUSED|ECONNRESET|EAI_AGAIN|network/i.test(msg) ? 'network error: ' : '';
  return `${code ? 'HTTP ' + code + ' ' : ''}${kind}${msg}`.trim();
};
const str = (v) => (v === undefined || v === null ? '' : String(v));
const out = [];
try {
for (const item of $input.all()) {
  const r = item.json;
  if (r.error || !Array.isArray(r.data)) { out.push(errorItem(errMsg(r))); continue; }
  for (const j of r.data) {
    out.push({ json: {
      _kind: 'job', source: SOURCE,
      sourceId: str(j.slug),
      title: str(j.title),
      company: str(j.company_name),
      descriptionHtml: str(j.description),
      location: str(j.location),
      remote: typeof j.remote === 'boolean' ? j.remote : null,
      employmentType: Array.isArray(j.job_types) ? j.job_types.join(', ') : '',
      salaryText: '',
      salaryStructured: null,
      // Arbeitnow `url` is sometimes a job page, sometimes a company homepage -> source URL only
      sourceUrl: str(j.url),
      applicationUrl: '',
      postedAt: j.created_at ? new Date(j.created_at * 1000).toISOString() : '',
      tags: Array.isArray(j.tags) ? j.tags.map(String) : [],
      remoteRegions: '',
      categoryTrusted: false,
    } });
  }
}
} catch (e) {
  out.length = 0;
  out.push(errorItem('Parsing error: ' + (e && e.message ? e.message : e)));
}
if (out.length === 0) out.push(errorItem('Empty response (0 jobs)'));
return out;

