  return `${code ? 'HTTP ' + code + ' ' : ''}${kind}${msg}`.trim();
};
const str = (v) => (v === undefined || v === null ? '' : String(v));
const out = [];
try {
for (const item of $input.all()) {
  const r = item.json;
  if (r.error || !Array.isArray(r.jobs)) { out.push(errorItem(errMsg(r))); continue; }
  for (const j of r.jobs) {
    const hasSalary = j.salaryMin != null || j.salaryMax != null;
    out.push({ json: {
      _kind: 'job', source: SOURCE,
      sourceId: str(j.id),
      title: str(j.jobTitle),
