      salaryStructured: hasSalary ? {
        min: j.salaryMin != null ? Number(j.salaryMin) : null,
        max: j.salaryMax != null ? Number(j.salaryMax) : null,
        currency: str(j.salaryCurrency),
        period: str(j.salaryPeriod),
      } : null,
      sourceUrl: str(j.url),
      applicationUrl: '',
      postedAt: str(j.pubDate),
      tags: [].concat(j.jobIndustry || [], j.jobLevel ? ['level: ' + j.jobLevel] : []).map(String),
      remoteRegions: str(j.jobGeo),
      categoryTrusted: true, // requested industry=dev
    } });
  }
}
} catch (e) {
  out.length = 0;
  out.push(errorItem('Parsing error: ' + (e && e.message ? e.message : e)));
}
if (out.length === 0) out.push(errorItem('Empty response (0 jobs)'));
return out;

const SOURCE = 'muse';
// Maps the raw API response to the minimal per-source shape. The shared
// "Normalize & Deduplicate" node does the heavy lifting (HTML, salary, keys).
//
// FAULT ISOLATION: this node never throws. Timeout, HTTP 4xx/5xx, 429, bad JSON,
// empty response or a parsing bug all become ONE `sourceError` item, so this
// source contributes zero jobs and every other source keeps going.
const errorItem = (message) => ({ json: { _kind: 'sourceError', source: SOURCE, message: String(message).slice(0, 500) } });
const errMsg = (r) => {
  const e = r && r.error;
  if (!e) return 'Malformed response (expected job list not found)';
  if (typeof e === 'string') return e;
  const code = e.httpCode || e.status || e.statusCode || (e.cause && e.cause.status);
  let msg = String(e.message || e.description || JSON.stringify(e));
  if (/<!doctype|<html/i.test(msg)) msg = msg.replace(/\s*-?\s*"?<!doctype[\s\S]*$|\s*-?\s*"?<html[\s\S]*$/i, '').trim() || 'HTML error page';
  msg = msg.split('\n')[0].replace(/^\d{3}\s*-?\s*/, '').slice(0, 160) || 'error';
  const kind = code ? '' : /timeout|ETIMEDOUT|ECONNABORTED/i.test(msg) ? 'timeout: ' : /ENOTFOUND|ECONNREFUSED|ECONNRESET|EAI_AGAIN|network/i.test(msg) ? 'network error: ' : '';
  return `${code ? 'HTTP ' + code + ' ' : ''}${kind}${msg}`.trim();
};
const str = (v) => (v === undefined || v === null ? '' : String(v));
const out = [];
try {
for (const item of $input.all()) {
  const r = item.json;
  if (r.error || !Array.isArray(r.results)) { out.push(errorItem(errMsg(r))); continue; }
  for (const j of r.results) {
    const locs = Array.isArray(j.locations) ? j.locations.map((l) => str(l.name)).filter(Boolean) : [];
    const isRemote = locs.some((l) => /remote|flexible/i.test(l));
    out.push({ json: {
      _kind: 'job', source: SOURCE,
      sourceId: str(j.id),
      title: str(j.name),
      company: str(j.company && j.company.name),
      descriptionHtml: str(j.contents),
      location: locs.join('; '),
      remote: isRemote,
      employmentType: Array.isArray(j.levels) ? j.levels.map((l) => l.name).join(', ') : '',
      salaryText: '',
      salaryStructured: null,
      sourceUrl: str(j.refs && j.refs.landing_page),
      applicationUrl: '',
      postedAt: str(j.publication_date),
      tags: [].concat(j.categories || [], j.levels || []).map((c) => str(c.name)),
      // Muse "Flexible / Remote" does not say which countries; other listed cities hint at the region
      remoteRegions: '',
      categoryTrusted: true, // requested category=Software Engineering
    } });
  }
}
} catch (e) {
  out.length = 0;
  out.push(errorItem('Parsing error: ' + (e && e.message ? e.message : e)));
}
if (out.length === 0) out.push(errorItem('Empty response (0 jobs)'));
return out;

// Source health for this run. Output = rows for the `job_hunt_runs` table:
// one row per FAILED source + one `run_summary` row whose message is the
// human-readable report (also sent to Discord every run, even with 0 matches).
//
// SOURCE REGISTRY — every known source and its state:
//   active          -> has Fetch + Normalize nodes wired into "Merge Job Sources"
//   not_configured  -> a legitimate public API exists, but it isn't set up yet
//   not_available   -> no permitted API/feed for this setup. Never scrape these.
// Statuses reported: SUCCESS / FAILED (active sources only), NOT CONFIGURED, NOT AVAILABLE.
// When you wire a new source, set its state to 'active'. A source that sends jobs
// but is missing here is treated as active automatically.
const SOURCE_REGISTRY = [
  { key: 'arbeitnow', label: 'Arbeitnow', state: 'active' },
  { key: 'remotive', label: 'Remotive', state: 'active' },
  { key: 'jobicy', label: 'Jobicy', state: 'active' },
  { key: 'muse', label: 'The Muse', state: 'active' },
  { key: 'greenhouse', label: 'Greenhouse', state: 'active' }, // company boards: config.atsBoards.greenhouse
  { key: 'lever', label: 'Lever', state: 'active' },           // company boards: config.atsBoards.lever
  { key: 'ashby', label: 'Ashby', state: 'not_configured', note: 'public job-board API, needs company list' },
  { key: 'linkedin', label: 'LinkedIn', state: 'not_available', note: 'no permitted API for this setup' },
  { key: 'naukri', label: 'Naukri', state: 'not_available', note: 'no public API' },
  { key: 'internshala', label: 'Internshala', state: 'not_available', note: 'no public API' },
  { key: 'indeed', label: 'Indeed', state: 'not_available', note: 'no public job-search API' },
  { key: 'glassdoor', label: 'Glassdoor', state: 'not_available', note: 'no public API' },
  { key: 'unstop', label: 'Unstop', state: 'not_available', note: 'no public API' },
  { key: 'cutshort', label: 'Cutshort', state: 'not_available', note: 'no public API' },
  { key: 'wellfound', label: 'Wellfound', state: 'not_available', note: 'no public API' },
  { key: 'instahyre', label: 'Instahyre', state: 'not_available', note: 'no public API' },
];

const runAt = $('Config & Profile').first().json.runStartedAt;
const all = $input.all().map((i) => i.json);
const jobs = all.filter((j) => j._kind === 'job');
const errors = all.filter((j) => j._kind === 'sourceError');
// Anything a Code node emitted after crashing (error item without _kind) counts as a failure too
const unknown = all.filter((j) => !j._kind);
const counts = jobs.reduce((acc, j) => ((acc[j.source] = (acc[j.source] || 0) + 1), acc), {});
// ATS sources can fail per company board; collect every error per source
const errBySource = errors.reduce((acc, e) => ((acc[e.source] = acc[e.source] || []).push(e.message), acc), {});
const notConfiguredNow = new Set(all.filter((j) => j._kind === 'sourceNotConfigured').map((j) => j.source));

const registry = [...SOURCE_REGISTRY];
for (const key of new Set([...Object.keys(counts), ...Object.keys(errBySource)])) {
  const known = registry.find((s) => s.key === key);
  if (!known) registry.push({ key, label: key, state: 'active' });
  else if (known.state !== 'active') known.state = 'active'; // wired up but registry not updated yet
}

const results = registry.map((s) => {
  if (s.state === 'not_configured' || notConfiguredNow.has(s.key)) return { ...s, status: 'NOT CONFIGURED', detail: s.note || 'no boards configured' };
  if (s.state === 'not_available') return { ...s, status: 'NOT AVAILABLE', detail: s.note || '' };
  const errs = errBySource[s.key] || [];
  // Partial success: some company boards worked -> SUCCESS, failed boards listed
  if (counts[s.key]) return { ...s, status: 'SUCCESS', detail: `${counts[s.key]} jobs${errs.length ? ` · ${errs.length} board(s) failed: ${errs.join('; ')}` : ''}`, errs };
  if (errs.length) return { ...s, status: 'FAILED', detail: errs.join('; '), errs };
  return { ...s, status: 'FAILED', detail: 'no output' };
});

const ICON = { SUCCESS: '✅', FAILED: '❌', 'NOT CONFIGURED': '⚙️', 'NOT AVAILABLE': '—' };
const line = (r) => `${r.label.padEnd(12)}${ICON[r.status]} ${r.status.padEnd(14)} ${String(r.detail).slice(0, 160)}`.trimEnd();
const active = results.filter((r) => r.status === 'SUCCESS' || r.status === 'FAILED');
const ok = active.filter((r) => r.status === 'SUCCESS').length;
const lines = [
  ...active.map(line),
  ...results.filter((r) => r.status === 'NOT CONFIGURED').map(line),
  ...results.filter((r) => r.status === 'NOT AVAILABLE').map(line),
];
if (unknown.length) lines.push(`(${unknown.length} unexpected error item(s) — see execution log)`);
const report = [
  'Sources:',
  ...lines,
  '',
  `Jobs collected: ${jobs.length}`,
  `Sources succeeded: ${ok}/${active.length} active`,
].join('\n');

// One row per failure (per board for ATS sources), including failed boards of a partially successful source
const rows = active.flatMap((r) => (r.errs && r.errs.length ? r.errs : r.status === 'FAILED' ? [r.detail] : [])
  .map((m) => ({ json: { runAt, kind: 'source_error', source: r.key, message: m, details: '' } })));
rows.push({ json: {
  runAt, kind: 'run_summary', source: 'all', message: report,
  details: JSON.stringify({
    jobsPerSource: counts,
    sourcesOk: ok,
    sourcesActive: active.length,
    statuses: Object.fromEntries(results.map((r) => [r.key, r.status])),
  }),
} });
return rows;

// Sends the source-health report every run. Returns nothing (-> no HTTP call)
// when no Discord webhook is configured; the report is still in job_hunt_runs.
const { config } = $('Config & Profile').first().json;
if (!config.discord?.healthWebhookUrl) return [];
const summary = $('Source Health Report').all().map((i) => i.json).find((r) => r.kind === 'run_summary');
return [{ json: { payload: {
  username: 'Job Hunt Agent',
  content: ('**Job Hunt Agent v2 — run ' + summary.runAt.slice(0, 16).replace('T', ' ') + ' UTC**\n```\n' + summary.message + '\n```').slice(0, 1990),
} } }];

// ---------- salary helpers (deterministic, never estimates) ----------
const NOT_DISCLOSED = () => ({ raw: 'Not disclosed', min: null, max: null, currency: '', period: '', disclosed: false, origin: '' });

const CUR_RE = '(?:₹|\\brs\\.?|\\binr\\b|us\\$|\\$|\\busd\\b|€|\\beur\\b|£|\\bgbp\\b|\\bcad\\b|\\baud\\b|\\bchf\\b|\\bsgd\\b)';
const NUM_RE = '\\d[\\d,.]*\\s?(?:k|m|lpa|lakhs?|lacs?|l|cr|crores?)?\\b';
const PERIOD_RE = '(?:\\s?(?:\\/|per|a|an|p\\.?)\\s?(?:month|mo|year|yr|annum|a|hour|hr|h|week|wk|day))';
const MONEY_RE = new RegExp(
