// ---------- text helpers ----------
const decode = (s) => String(s ?? '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#0?39;|&apos;|&rsquo;|&lsquo;/g, "'").replace(/&[lr]dquo;/g, '"')
  .replace(/&ndash;|&mdash;/g, '-').replace(/&#(\d+);/g, (m, d) => String.fromCharCode(+d));
const htmlToText = (html) => decode(String(html || '')
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|li|h[1-6]|tr|ul|ol)>/gi, '\n')
  .replace(/<li[^>]*>/gi, '• ')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t\f\r\v]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();

// ---------- application URL: only when the posting itself links to an ATS / apply page ----------
const SOURCE_DOMAINS = /(arbeitnow\.com|remotive\.com|jobicy\.com|themuse\.com)/i;
const APPLY_URL = /(greenhouse\.io|lever\.co|ashbyhq\.com|workable\.com|smartrecruiters\.com|myworkdayjobs\.com|personio\.(de|com)|recruitee\.com|bamboohr\.com|breezy\.hr|jobvite\.com|teamtailor\.com|join\.com|wellfound\.com\/jobs|\/apply\b|\/careers?\/.+|\/jobs?\/.+)/i;
function extractApplicationUrl(html) {
  const links = [...String(html || '').matchAll(/<a\s[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)]
    .map((m) => ({ url: decode(m[1]).trim(), text: htmlToText(m[2]).toLowerCase() }))
    .filter((l) => /^https?:\/\//i.test(l.url) && !SOURCE_DOMAINS.test(l.url));
  const byText = links.find((l) => /apply|bewerb/.test(l.text));
  if (byText) return byText.url;
  const byUrl = links.find((l) => APPLY_URL.test(l.url));
  return byUrl ? byUrl.url : '';
}
function canonicalUrl(u) {
  try {
    const x = new URL(u);
    [...x.searchParams.keys()].forEach((k) => { if (/^(utm_|ref|source|gh_src|lever-source)/i.test(k)) x.searchParams.delete(k); });
    return (x.hostname.replace(/^www\./, '') + x.pathname.replace(/\/+$/, '') + (x.search || '')).toLowerCase();
