// ---------- dedupe keys ----------
const normCompany = (s) => decode(s).toLowerCase()
  .replace(/\b(gmbh|inc|ltd|llc|pvt|private|limited|ag|se|co|corp|corporation|plc|bv|sas|sa|the)\b\.?/g, ' ')
  .replace(/[^a-z0-9]+/g, ' ').trim();
const normTitle = (s) => decode(s).toLowerCase()
  .replace(/\((?:[mwfdxh]\s*\/\s*)+[mwfdxh]\)|\(all genders?\)|\(gn\)/g, ' ')
  .replace(/[-–|(]\s*(100%\s*)?remote\b.*$/, ' ')
  .replace(/[^a-z0-9+#.]+/g, ' ').replace(/\s+/g, ' ').trim();
const normLoc = (job) => (job.remote ? 'remote' : decode(job.location).toLowerCase().split(/[;,/]/)[0].replace(/[^a-z ]/g, '').trim());

// ---------- heuristics used by the filter & for the AI ----------
function seniorityOf(title) {
  const t = title.toLowerCase();
  if (/\b(intern|internship|trainee|werkstudent|working student|praktikum|praktikant|apprentice|co-op)\b/.test(t)) return 'internship';
  if (/\b(junior|jr\.?|graduate|grad|entry[- ]level|fresher|associate)\b/.test(t)) return 'junior';
  if (/\b(senior|sr\.?|lead|principal|staff|head|director|manager|architect|vp|chief|expert)\b/.test(t)) return 'senior';
  return 'unknown';
}
