// ---------- main ----------
const nowIso = new Date().toISOString();
const SOURCE_PRIORITY = ['greenhouse', 'lever', 'remotive', 'jobicy', 'muse', 'arbeitnow']; // direct company postings first when merging
const rank = (s) => (SOURCE_PRIORITY.includes(s) ? SOURCE_PRIORITY.indexOf(s) : SOURCE_PRIORITY.length); // unknown/new sources last
const all = $input.all().map((i) => i.json);
const jobs = all.filter((j) => j._kind === 'job')
  .sort((a, b) => rank(a.source) - rank(b.source));
const sourceErrors = all.filter((j) => j._kind === 'sourceError');

const byKey = new Map();
const keyBySourceId = new Map();
const keyByAppUrl = new Map();
let duplicates = 0;

for (const r of jobs) {
  const title = decode(r.title).trim();
  const company = decode(r.company).trim();
  if (!title) continue;
