  let salary = NOT_DISCLOSED();
  if (r.salaryStructured && (r.salaryStructured.min != null || r.salaryStructured.max != null)) {
    const s = r.salaryStructured;
    const lo = s.min ?? s.max, hi = s.max ?? s.min;
