  const applicationUrl = r.applicationUrl || extractApplicationUrl(r.descriptionHtml);
  const job = {
    jobKey: '',
    title,
    company,
    description,
    location: decode(r.location).trim(),
    remote: r.remote,
    remoteRegions: decode(r.remoteRegions).trim(),
    employmentType: r.employmentType || '',
    salary,
    source: r.source,
    sources: [{ source: r.source, sourceId: r.sourceId, sourceUrl: r.sourceUrl }],
    sourceId: r.sourceId,
    sourceUrl: r.sourceUrl,
    applicationUrl,
    applicationUrlOrigin: r.applicationUrl ? 'source' : (applicationUrl ? 'link found in description' : ''),
    postedAt: r.postedAt || '',
    updatedAt: r.updatedAt || '',
    discoveredAt: nowIso,
    tags: Array.isArray(r.tags) ? r.tags : [],
    categoryTrusted: !!r.categoryTrusted,
    seniority: seniorityOf(title),
    minYearsRequired: minYearsRequired(description),
  };
