  // Match existing logical job by: same source id -> same application URL -> company+title+location
  const sid = `${job.source}:${job.sourceId}`;
  const appKey = applicationUrl ? canonicalUrl(applicationUrl) : '';
  const existingKey = keyBySourceId.get(sid) || (appKey && keyByAppUrl.get(appKey)) || (byKey.has(job.jobKey) ? job.jobKey : null);

  if (existingKey) {
    duplicates++;
    const e = byKey.get(existingKey);
    if (!e.sources.some((s) => s.source === job.source)) e.sources.push(job.sources[0]); // one entry per source
    if (!e.salary.disclosed && job.salary.disclosed) e.salary = job.salary;
    if (!e.applicationUrl && job.applicationUrl) { e.applicationUrl = job.applicationUrl; e.applicationUrlOrigin = job.applicationUrlOrigin; }
    if (job.description.length > e.description.length) e.description = job.description;
    e.tags = [...new Set([...e.tags, ...job.tags])];
    keyBySourceId.set(sid, existingKey);
