  collected: jobs.length,
  unique: byKey.size,
  duplicatesMerged: duplicates,
  failedSources: sourceErrors.map((e) => e.source),
  perSource: jobs.reduce((acc, j) => ((acc[j.source] = (acc[j.source] || 0) + 1), acc), {}),
