// Stage 1: cheap deterministic filter. Only drops OBVIOUS mismatches;
// anything borderline goes to Qwen. Each kept job gets a prefilterScore used
// to pick which jobs get AI time when there are more than maxAiJobsPerRun.
const { config, skillList } = $('Config & Profile').first().json;
const policy = config.locationPolicy;

const POSITIVE = [
  /\bsoftware\b/, /\b(developer|entwickler|programmer|sde|swe)\b/, /\bsoftwareentwickler/,
  /\b(front|back)[\s-]?end\b/, /\bfull[\s-]?stack\b/, /\bweb\b/,
  /\b(javascript|typescript|react|node(\.?js)?|next\.?js|vue|angular|python|java|golang|ruby|php|\.net|rust|kotlin|swift)\b/,
  /\b(devops|sre|site reliability|platform engineer|cloud engineer|infrastructure engineer|data engineer|ml engineer|ai engineer|machine learning engineer|qa engineer|test automation|automation engineer|api)\b/,
  /\b(engineering|software|developer|sde|tech|it) (intern|internship|trainee)\b/, /\bintern(ship)?\b.*\b(engineer|developer|software)\b/,
