const NEGATIVE = /\b(sales|account executive|account manager|marketing|recruit(er|ing)|talent|hr|human resources|accountant|accounting|finance|nurse|driver|customer (service|success|support)|kundenservice|support agent|call center|writer|copywriter|content (reviewer|moderator|creator)|translator|evaluator|rater|annotator|data entry|teacher|tutor|lawyer|legal|paralegal|office assistant|receptionist|mechanic|electrician|mechanical|electrical|civil|chemical|warehouse|logistics|business development|product manager|project manager|scrum master|graphic designer|consultant|sap|medical|clinical|oncology|pharma\w*|linguist\w*)\b/;
const SENIOR = /\b(senior|sr\.?|lead|principal|staff|head of|director|manager|architect|vp|chief|expert)\b|\b(engineer|developer|sde|swe)\s*(iii|iv|3|4)\b/;

