// One Discord message per READY package (+ a header). Returns [] when no webhook is set.
// Packages that failed validation (status REVIEW_REQUIRED) are only counted, never announced as ready.
const { config } = $('Config & Profile').first().json;
const packaged = $input.all().map((i) => i.json).sort((a, b) => (b.matchScore || 0) - (a.matchScore || 0));
const rows = packaged.filter((r) => r.status !== 'REVIEW_REQUIRED');
const packagesNeedingReview = packaged.length - rows.length;
const shortlistedTotal = $('Store Job').all().filter((i) => i.json.status === 'SHORTLISTED').length;
const analysesNeedingReview = $('Store Job').all().filter((i) => i.json.status === 'REVIEW_REQUIRED').length;
const analyzedTotal = $('Store Job').all().length;
if (!config.discord?.jobsWebhookUrl || packaged.length === 0) return [];
const reviewNote = packagesNeedingReview || analysesNeedingReview
  ? ` ${packagesNeedingReview + analysesNeedingReview} job(s) need review in the Tracker (status REVIEW_REQUIRED) — not ready to apply.` : '';

const bullets = (s, n) => String(s || '').split('\n').filter(Boolean).slice(0, n).map((x) => `• ${x}`).join('\n') || '• —';
const remoteLabel = (r) => (r === true ? 'Yes' : r === false ? 'No' : 'Unknown');
const msgs = [{
  username: 'Job Hunt Agent',
  content: `**${rows.length} new application package(s) ready** (analyzed ${analyzedTotal}, shortlisted ${shortlistedTotal}).${reviewNote} Tracker: ${config.trackerBaseUrl}`,
}];
for (const r of rows) {
  const apply = r.applicationUrl
    ? `Application: ${r.applicationUrl}`
    : `Application: no direct apply link found — open the listing: ${r.sourceUrl}`;
  const text = [
    `**${r.title}**`,
    `Company: ${r.company || 'Unknown'}`,
    '',
    `Compensation: ${r.salaryRaw || 'Not disclosed'}`,
    `Location: ${r.location || 'Unknown'}`,
    `Remote: ${remoteLabel(r.remote)}`,
    '',
    `Match: ${r.matchScore} (${r.matchLevel}, recommendation: ${r.recommendation})`,
    '',
    'Why:', bullets(r.why, 4),
    '',
    'Gaps:', bullets([r.missingSkills, r.experienceGap, r.languageRequirement].filter(Boolean).join('\n'), 5),
    '',
    apply,
    `Source: ${JSON.parse(r.sources || '[]').map((s) => s.source).join(', ') || r.source} — ${r.sourceUrl}`,
    `Resume / cover letter / answers: ${config.trackerBaseUrl}/job?id=${r.id}`,
    r.notes ? `\n⚠️ ${r.notes.split('\n')[0]}` : '',
