// One item per configured board -> one HTTP request each (1 s apart).
// Boards live in Config & Profile -> config.atsBoards.greenhouse ; verify a board before adding it.
const { config } = $('Config & Profile').first().json;
const boards = ((config.atsBoards || {}).greenhouse || []).filter((b) => b && b.board);
if (!boards.length) return [{ json: { notConfigured: true, url: '' } }]; // reported as NOT CONFIGURED
return boards.map((b) => ({ json: { board: String(b.board), company: String(b.company || b.board), url: `https://boards-api.greenhouse.io/v1/boards/${encodeURIComponent(b.board)}/jobs?content=true&pay_transparency=true` } }));

const SOURCE = 'greenhouse';
const LIST_NODE = 'List Greenhouse Boards';
// Company job boards via a PUBLIC ATS API (no login). One HTTP item per board.
// FAULT ISOLATION: never throws. A failing board becomes one `sourceError` item
// (tagged with the board) and every other board and source keeps going.
const str = (v) => (v === undefined || v === null ? '' : String(v));
const errMsg = (r) => {
  const e = r && r.error;
  if (!e) return 'Malformed response (expected job list not found)';
  if (typeof e === 'string') return e;
  const code = e.httpCode || e.status || e.statusCode || (e.cause && e.cause.status);
  let msg = String(e.message || e.description || JSON.stringify(e));
  if (/<!doctype|<html/i.test(msg)) msg = msg.replace(/\s*-?\s*"?<!doctype[\s\S]*$|\s*-?\s*"?<html[\s\S]*$/i, '').trim() || 'HTML error page';
  msg = msg.split('\n')[0].replace(/^\d{3}\s*-?\s*/, '').slice(0, 160) || 'error';
  const kind = code ? '' : /timeout|ETIMEDOUT|ECONNABORTED/i.test(msg) ? 'timeout: ' : /ENOTFOUND|ECONNREFUSED|ECONNRESET|EAI_AGAIN|network/i.test(msg) ? 'network error: ' : '';
  return `${code ? 'HTTP ' + code + ' ' : ''}${kind}${msg}`.trim();
};
const boardError = (b, message) => ({ json: { _kind: 'sourceError', source: SOURCE, board: str(b.board), message: `${b.company || b.board || 'unknown board'}: ${String(message).slice(0, 300)}` } });
// Which configured board produced this HTTP item (order + pairedItem are preserved by the HTTP node)
const boards = $(LIST_NODE).all().map((i) => i.json);
const boardFor = (item, i) => {
  const p = item.pairedItem;
  const idx = Array.isArray(p) ? p[0] && p[0].item : p && typeof p === 'object' ? p.item : p;
  return boards[Number.isInteger(idx) ? idx : i] || {};
};
if (boards.length === 1 && boards[0].notConfigured) {
  return [{ json: { _kind: 'sourceNotConfigured', source: SOURCE, message: 'no boards in config.atsBoards' } }];
}
const out = [];
// Greenhouse Job Board API: GET boards-api.greenhouse.io/v1/boards/{board}/jobs?content=true&pay_transparency=true
const decodeEntities = (s) => str(s).replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
$input.all().forEach((item, i) => {
  const b = boardFor(item, i);
  try {
    const r = item.json;
    if (r.error || !Array.isArray(r.jobs)) { out.push(boardError(b, errMsg(r))); return; }
    for (const j of r.jobs) {
      const locName = str(j.location && j.location.name) ||
        (Array.isArray(j.offices) ? j.offices.map((o) => o.location || o.name).filter(Boolean).join('; ') : '');
      const isRemote = /remote/i.test(locName) ? true : locName ? false : null;
      const meta = Array.isArray(j.metadata) ? j.metadata : [];
      const empType = meta.find((m) => /employment|job type|commitment|contract type/i.test(str(m.name)));
      // Employer-published pay range (pay transparency). Kept as text WITH its label,
      // e.g. "(United States Salary Range)", so a region-specific range is never mistaken for India pay.
      const ranges = Array.isArray(j.pay_input_ranges) ? j.pay_input_ranges : [];
      const pr = ranges.find((p) => /india/i.test(str(p.title))) || ranges[0];
      const money = (c) => (c === null || c === undefined ? '' : Math.round(Number(c) / 100).toLocaleString('en-US'));
      const salaryText = pr && (pr.min_cents != null || pr.max_cents != null)
        ? `${str(pr.currency_type)} ${[money(pr.min_cents), money(pr.max_cents)].filter(Boolean).join(' - ')}${pr.title ? ' (' + str(pr.title) + ')' : ''}`.trim()
        : '';
      out.push({ json: {
        _kind: 'job', source: SOURCE,
        sourceId: `${b.board}:${j.id}`,
        title: str(j.title),
        company: b.company || str(j.company_name),
        descriptionHtml: decodeEntities(j.content), // Greenhouse returns entity-encoded HTML
        location: locName,
        remote: isRemote,
        employmentType: empType ? str(empType.value) : '',
        salaryText,
        salaryStructured: null,
        sourceUrl: str(j.absolute_url),
        applicationUrl: str(j.absolute_url), // direct company posting with the application form
        postedAt: str(j.first_published || j.updated_at),
        updatedAt: str(j.updated_at),
        tags: [...(Array.isArray(j.departments) ? j.departments.map((d) => str(d.name)) : []), 'ATS: Greenhouse', `board: ${b.board}`].filter(Boolean),
        remoteRegions: isRemote ? locName.replace(/\bremote\b[\s,\-–:]*/i, '').trim() : '',
        categoryTrusted: false, // boards list every department -> needs a software keyword
      } });
    }
  } catch (e) {
    out.push(boardError(b, 'Parsing error: ' + (e && e.message ? e.message : e)));
  }
});
if (out.length === 0) out.push({ json: { _kind: 'sourceError', source: SOURCE, board: '', message: 'Empty response (0 jobs on all boards)' } });
return out;

