}
const out = [];
// Lever Postings API: GET api.lever.co/v0/postings/{board}?mode=json
// The HTTP node fetches it as TEXT so each board stays one item; parsed here.
const PERIOD = { 'per-year-salary': 'year', 'per-month-salary': 'month', 'per-week-salary': 'week', 'per-day-wage': 'day', 'per-hour-wage': 'hour' };
const COUNTRY = { IN: 'India', US: 'United States', GB: 'United Kingdom', SG: 'Singapore', AE: 'United Arab Emirates', DE: 'Germany' };
$input.all().forEach((item, i) => {
  const b = boardFor(item, i);
  try {
    const r = item.json;
    if (r.error) { out.push(boardError(b, errMsg(r))); return; }
    let arr;
    try { arr = typeof r.data === 'string' ? JSON.parse(r.data) : r.data; } catch { out.push(boardError(b, 'Malformed JSON')); return; }
    if (!Array.isArray(arr)) { out.push(boardError(b, (arr && (arr.error || arr.message)) || 'Malformed response (expected job list)')); return; }
    for (const p of arr) {
