      const loc = str(c.location) || (Array.isArray(c.allLocations) ? c.allLocations.join('; ') : '');
      const country = COUNTRY[p.country] || str(p.country);
      const location = loc && country && !loc.toLowerCase().includes(country.toLowerCase()) ? `${loc}, ${country}` : loc || country;
